class VersionedKV:
    def __init__(self):
        self._working = {}
        self._snapshots = []

    def set(self, key, value) -> None:
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        del self._working[key]

    def get(self, key):
        if key not in self._working:
            raise KeyError(key)
        return self._working[key]

    def has(self, key) -> bool:
        return key in self._working

    def commit(self) -> int:
        self._snapshots.append(dict(self._working))
        return len(self._snapshots)

    def get_at(self, key, version):
        if not (1 <= version <= len(self._snapshots)):
            raise ValueError(f"version must be between 1 and {len(self._snapshots)}")
        snapshot = self._snapshots[version - 1]
        if key not in snapshot:
            raise KeyError(key)
        return snapshot[key]

    def rollback(self, version) -> None:
        if not (0 <= version <= len(self._snapshots)):
            raise ValueError(f"version must be between 0 and {len(self._snapshots)}")
        if version == 0:
            self._working = {}
        else:
            self._working = dict(self._snapshots[version - 1])

    def latest(self) -> int:
        return len(self._snapshots)

class UndoStack:
    def __init__(self):
        self._stack = []
        self._history = []

    def push(self, x) -> None:
        self._stack.append(x)
        self._history.append(('push', x))

    def pop(self):
        if not self._stack:
            raise IndexError("pop from empty stack")
        value = self._stack.pop()
        self._history.append(('pop', value))
        return value

    def peek(self):
        if not self._stack:
            raise IndexError("peek from empty stack")
        return self._stack[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, value = self._history.pop()
        if op == 'push':
            self._stack.pop()
        else:  # op == 'pop'
            self._stack.append(value)

    def __len__(self) -> int:
        return len(self._stack)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0:
        return []

    counts = {}
    first_index = {}
    for idx, value in enumerate(items):
        if value not in counts:
            counts[value] = 0
            first_index[value] = idx
        counts[value] += 1

    distinct = list(counts.keys())
    n = len(distinct)
    remaining = [True] * n
    result = []

    limit = k if k < n else n
    for _ in range(limit):
        best_pos = -1
        for pos in range(n):
            if not remaining[pos]:
                continue
            if best_pos == -1:
                best_pos = pos
                continue
            a = distinct[pos]
            b = distinct[best_pos]
            if counts[a] > counts[b]:
                best_pos = pos
            elif counts[a] == counts[b] and first_index[a] < first_index[b]:
                best_pos = pos

        remaining[best_pos] = False
        value = distinct[best_pos]
        result.append((value, counts[value]))

    return result

from collections import deque

def count_stable_windows(readings: list[int], tol: int) -> int:
    n = len(readings)
    max_deque = deque()
    min_deque = deque()
    left = 0
    total = 0

    for right in range(n):
        val = readings[right]

        while max_deque and readings[max_deque[-1]] <= val:
            max_deque.pop()
        max_deque.append(right)

        while min_deque and readings[min_deque[-1]] >= val:
            min_deque.pop()
        min_deque.append(right)

        while readings[max_deque[0]] - readings[min_deque[0]] > tol:
            left += 1
            while max_deque and max_deque[0] < left:
                max_deque.popleft()
            while min_deque and min_deque[0] < left:
                min_deque.popleft()

        total += right - left + 1

    return total

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def purge_expired(sessions, now):
