class TaskScheduler:
    def __init__(self):
        self.heap = []  # entries: (-priority, seq, version, task_id)
        self.active = {}  # task_id -> (priority, seq, version)
        self.seq_counter = 0
        self.version_counter = 0

    def submit(self, task_id, priority):
        if task_id in self.active:
            raise ValueError(f"Task {task_id} is already active")
        seq = self.seq_counter
        self.seq_counter += 1
        version = self.version_counter
        self.version_counter += 1
        self.active[task_id] = (priority, seq, version)
        heapq.heappush(self.heap, (-priority, seq, version, task_id))

    def reprioritize(self, task_id, priority):
        if task_id not in self.active:
            raise KeyError(f"Task {task_id} is not active")
        seq = self.active[task_id][1]
        version = self.version_counter
        self.version_counter += 1
        self.active[task_id] = (priority, seq, version)
        heapq.heappush(self.heap, (-priority, seq, version, task_id))

    def cancel(self, task_id):
        if task_id not in self.active:
            raise KeyError(f"Task {task_id} is not active")
        del self.active[task_id]

    def pop(self):
        while self.heap:
            neg_priority, seq, version, task_id = self.heap[0]
            if task_id in self.active and self.active[task_id][2] == version:
                heapq.heappop(self.heap)
                del self.active[task_id]
                return task_id
            heapq.heappop(self.heap)
        raise IndexError("pop from empty scheduler")

    def peek(self):
        while self.heap:
            neg_priority, seq, version, task_id = self.heap[0]
            if task_id in self.active and self.active[task_id][2] == version:
                return task_id
            heapq.heappop(self.heap)
        raise IndexError("peek from empty scheduler")

    def priority_of(self, task_id):
        if task_id not in self.active:
            raise KeyError(f"Task {task_id} is not active")
        return self.active[task_id][0]

    def __len__(self):
        return len(self.active)

