def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")

    if _has_empty(segments, 0):
        raise ValueError("empty segment")

    return _navigate(data, segments, 0)


def _has_empty(segments, i):
    if i >= len(segments):
        return False
    if segments[i] == "":
        return True
    return _has_empty(segments, i + 1)


def _navigate(data, segments, i):
    if i >= len(segments):
        return data

    seg = segments[i]

    if isinstance(data, dict):
        if seg not in data:
            raise KeyError(seg)
        return _navigate(data[seg], segments, i + 1)

    if isinstance(data, list):
        if not _is_valid_int_literal(seg):
            raise ValueError("invalid index: " + seg)
        idx = int(seg)
        if idx < -len(data) or idx >= len(data):
            raise IndexError(seg)
        return _navigate(data[idx], segments, i + 1)

    raise TypeError("cannot descend into non-container at segment: " + seg)


def _is_valid_int_literal(s):
    if s == "":
        return False
    if s[0] == "-":
        rest = s[1:]
        if rest == "":
            return False
        return _all_digits(rest, 0)
    return _all_digits(s, 0)


def _all_digits(s, i):
    if i >= len(s):
        return True
    if not ("0" <= s[i] <= "9"):
        return False
    return _all_digits(s, i + 1)

def recurring_counts(data: list[int], queries: list[tuple[int, int]]) -> list[int]:
    n = len(data)
    if n == 0:
        return [0] * len(queries)

    events = []
    last = {}
    second_last = {}

    for i, v in enumerate(data):
        if v in last:
            l_prev = last[v]
            l2_prev = second_last.get(v, -1)
            events.append((l2_prev + 1, 1, i))
            events.append((l_prev + 1, -1, i))
            second_last[v] = l_prev
            last[v] = i
        else:
            last[v] = i

    events.sort(key=lambda x: x[0])

    bit = [0] * (n + 2)

    def bit_add(idx: int, delta: int) -> None:
        idx += 1
        while idx <= n:
            bit[idx] += delta
            idx += idx & -idx

    def bit_sum(idx: int) -> int:
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s

    q = len(queries)
    ans = [0] * q
    sorted_queries = sorted([(l, r, i) for i, (l, r) in enumerate(queries)], key=lambda x: x[0])

    ev_idx = 0
    ev_len = len(events)
    for l, r, idx in sorted_queries:
        while ev_idx < ev_len and events[ev_idx][0] <= l:
            _, delta, i = events[ev_idx]
            bit_add(i, delta)
            ev_idx += 1
        ans[idx] = bit_sum(r)

    return ans

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")

    def is_literal(s):
        if not s:
            return False
        start = 1 if s[0] in "+-" else 0
        if start == len(s):
            return False
        for ch in s[start:]:
            if ch < "0" or ch > "9":
                return False
        return True

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(f"token {i} is not a string")

        if tok in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()

            if tok == "+":
                stack.append(left + right)
            elif tok == "-":
                stack.append(left - right)
            elif tok == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                q = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    q = -q
                stack.append(q)
        else:
            if not is_literal(tok):
                raise ValueError(f"unknown token {tok!r} at token {i}")
            stack.append(int(tok))

    if len(stack) != 1:
        raise ValueError("leftover operands")
    return stack[0]

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    def is_name_char(ch):
        return ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ('0' <= ch <= '9') or ch == '_'

    result = []
    i = 0
    n = len(template)

    while i < n:
        c = template[i]
        if c == "{":
            if i + 1 < n and template[i + 1] == "{":
                result.append("{")
                i += 2
                continue
            p = i
            j = i + 1
            if j >= n:
                raise ValueError("unclosed placeholder at position " + str(p))
            if template[j] == "}":
                raise ValueError("empty placeholder at position " + str(p))
            if not is_name_char(template[j]):
                raise ValueError("invalid placeholder at position " + str(p))
            name_chars = []
            while j < n and is_name_char(template[j]):
                name_chars.append(template[j])
                j += 1
            if j >= n:
                raise ValueError("unclosed placeholder at position " + str(p))
            if template[j] != "}":
                raise ValueError("invalid placeholder at position " + str(p))
            name = "".join(name_chars)
            if name not in context:
                raise KeyError(name)
            result.append(str(context[name]))
            i = j + 1
        elif c == "}":
            if i + 1 < n and template[i + 1] == "}":
                result.append("}")
                i += 2
                continue
            raise ValueError("stray '}' at position " + str(i))
        else:
            result.append(c)
            i += 1

    return "".join(result)

from collections import defaultdict

def peak_load(intervals: list[tuple[int, int]]) -> tuple[int, int]:
    delta = defaultdict(int)
    for s, e in intervals:
        delta[s] += 1
        delta[e] -= 1

    max_load = 0
    earliest_t = 0
    current_load = 0

    for t in sorted(delta):
        current_load += delta[t]
        if current_load > max_load:
            max_load = current_load
            earliest_t = t

    return (max_load, earliest_t)

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        curr = ordered[i]
        if curr[0] == prev[0] or curr[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    result = list(lines)
    offset = 0
    for start, delete, insert in ordered:
        actual_start = start + offset
        result[actual_start:actual_start + delete] = list(insert)
        offset += len(insert) - delete
    return result

def count_locked_pairs(values: list[int], m: int) -> int:
    if m < 1:
        raise ValueError("m must be >= 1")
    if not values:
        return 0

    cnt_even = [0] * m
    cnt_odd = [0] * m

    for v in values:
        r = v % m
        if v & 1:
            cnt_odd[r] += 1
        else:
            cnt_even[r] += 1

    total = 0
    for r in range(m):
        rc = (m - r) % m

        c_even = cnt_even[r]
        if c_even:
            if rc == r:
                total += c_even * (c_even - 1) // 2
            elif rc > r:
                total += c_even * cnt_even[rc]

        c_odd = cnt_odd[r]
        if c_odd:
            if rc == r:
                total += c_odd * (c_odd - 1) // 2
            elif rc > r:
                total += c_odd * cnt_odd[rc]

    return total

def min_insertions(s, allowed):
    n = len(s)
    if n <= 1:
        return 0
    allowed_set = set(allowed)
    INF = 10**9
    dp = [[0] * n for _ in range(n)]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1]
            else:
                res = INF
                if s[i] in allowed_set:
                    res = min(res, 1 + dp[i + 1][j])
                if s[j] in allowed_set:
                    res = min(res, 1 + dp[i][j - 1])
                dp[i][j] = res
    ans = dp[0][n - 1]
    return ans if ans < INF else -1

import math

def vector_norm(v: list[float]) -> float:
    if not v:
        return 0.0
    for x in v:
        if math.isnan(x) or math.isinf(x):
            raise ValueError
    norm = 0.0
    for x in v:
        norm = math.hypot(norm, x)
    return norm

class IntervalSet:
    def __init__(self):
        self._intervals = []  # sorted list of (lo, hi), normalized

    def add(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be less than hi")
        new_intervals = []
        i = 0
        n = len(self._intervals)
        while i < n and self._intervals[i][1] < lo:
            new_intervals.append(self._intervals[i])
            i += 1
        start, end = lo, hi
        while i < n and self._intervals[i][0] <= hi:
            start = min(start, self._intervals[i][0])
            end = max(end, self._intervals[i][1])
            i += 1
        new_intervals.append((start, end))
        while i < n:
            new_intervals.append(self._intervals[i])
            i += 1
        self._intervals = new_intervals

    def remove(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be less than hi")
        new_intervals = []
        for ilo, ihi in self._intervals:
            if ihi <= lo or ilo >= hi:
                new_intervals.append((ilo, ihi))
            else:
                if ilo < lo:
                    new_intervals.append((ilo, lo))
                if ihi > hi:
                    new_intervals.append((hi, ihi))
        self._intervals = new_intervals

    def contains(self, x):
        for lo, hi in self._intervals:
            if lo <= x < hi:
                return True
            if lo > x:
                break
        return False

    def total(self):
        return sum(hi - lo for lo, hi in self._intervals)

    def intervals(self):
        return list(self._intervals)

    def gaps(self, lo, hi):
        if lo >= hi:
            raise ValueError("lo must be less than hi")
        result = []
        current = lo
        for ilo, ihi in self._intervals:
            if ihi <= current:
                continue
            if ilo >= hi:
                break
            if ilo > current:
                result.append((current, min(ilo, hi)))
            current = max(current, ihi)
            if current >= hi:
                break
        if current < hi:
            result.append((current, hi))
        return result

class MergeLedger:
    def __init__(self):
        self._parent = {}
        self._size = {}
        self._sum = {}
        self._value = {}
        self._num_components = 0
        self._stack = []

    def add(self, x, value=0):
        if x in self._parent:
            raise ValueError(f"{x!r} already exists")
        self._parent[x] = x
        self._size[x] = 1
        self._sum[x] = value
        self._value[x] = value
        self._num_components += 1

    def _find(self, x):
        root = x
        while self._parent[root] != root:
            root = self._parent[root]
        return root

    def merge(self, a, b):
        if a not in self._parent:
            raise KeyError(a)
        if b not in self._parent:
            raise KeyError(b)
        ra = self._find(a)
        rb = self._find(b)
        if ra == rb:
            return False
        if self._size[ra] < self._size[rb]:
            ra, rb = rb, ra
        self._parent[rb] = ra
        self._size[ra] += self._size[rb]
        self._sum[ra] += self._sum[rb]
        self._stack.append((rb, ra))
        self._num_components -= 1
        return True

    def same(self, a, b):
        if a not in self._parent:
            raise KeyError(a)
        if b not in self._parent:
            raise KeyError(b)
        return self._find(a) == self._find(b)

    def component_size(self, x):
        if x not in self._parent:
            raise KeyError(x)
        return self._size[self._find(x)]

    def component_value(self, x):
        if x not in self._parent:
            raise KeyError(x)
        return self._sum[self._find(x)]

    def add_value(self, x, delta):
        if x not in self._parent:
            raise KeyError(x)
        self._value[x] += delta
        node = x
        while True:
            self._sum[node] += delta
            if self._parent[node] == node:
                break
            node = self._parent[node]

    def components(self):
        return self._num_components

    def undo(self):
        if not self._stack:
            raise RuntimeError("no merge to undo")
        child, parent = self._stack.pop()
        self._parent[child] = child
        self._size[parent] -= self._size[child]
        self._sum[parent] -= self._sum[child]
        self._num_components += 1

def weighted_median(values: list, weights: list) -> float:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")

    W = sum(weights)
    if W <= 0:
        raise ValueError("sum of weights must be positive")

    threshold = W / 2 - 1e-9
    cumulative = 0.0

    for v, w in sorted(zip(values, weights), key=lambda x: x[0]):
        cumulative += w
        if cumulative >= threshold:
            return v

def longest_spaced_repeat(s, gap):
    n = len(s)
    # lcp[i][j] = length of longest common prefix of suffixes starting at i and j
    # Extra row/col of zeros avoids bounds checking.
    lcp = [[0] * (n + 1) for _ in range(n + 1)]
    max_len = 0
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if s[i] == s[j]:
                lcp[i][j] = 1 + lcp[i + 1][j + 1]
            if i < j and j - i - gap >= 1:
                cand = min(lcp[i][j], j - i - gap)
                if cand > max_len:
                    max_len = cand
    return max_len

import re

def compute_balances(transactions):
    balances = {}
    pattern = re.compile(r'^([0-9]+)(?:\.([0-9]{1,2}))?$')
    for tx in transactions:
        m = pattern.match(tx["amount"])
        if not m:
            raise ValueError("invalid amount")
        whole = m.group(1)
        frac = m.group(2)
        cents = int(whole) * 100
        if frac:
            if len(frac) == 1:
                cents += int(frac) * 10
            else:
                cents += int(frac)
        if cents <= 0:
            raise ValueError("amount must be positive")
        balances[tx["from"]] = balances.get(tx["from"], 0) - cents
        balances[tx["to"]] = balances.get(tx["to"], 0) + cents
    return balances

class Leaderboard:
    def __init__(self):
        self._best = {}
        self._time = {}
        self._clock = 0

    def submit(self, player, score):
        if player not in self._best or score > self._best[player]:
            self._best[player] = score
            self._time[player] = self._clock
            self._clock += 1
            return True
        return False

    def best(self, player):
        if player not in self._best:
            raise KeyError(player)
        return self._best[player]

    def rank(self, player):
        if player not in self._best:
            raise KeyError(player)
        score = self._best[player]
        return 1 + sum(1 for s in self._best.values() if s > score)

    def top(self, k):
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        players = sorted(self._best.keys(), key=lambda p: (-self._best[p], self._time[p]))
        if k > len(players):
            k = len(players)
        return [(p, self._best[p]) for p in players[:k]]

    def player_count(self):
        return len(self._best)

def round_robin(iterables: list) -> "iterator":
    iterators = [iter(it) for it in iterables]
    while iterators:
        next_iterators = []
        for it in iterators:
            try:
                value = next(it)
            except StopIteration:
                continue
            yield value
            next_iterators.append(it)
        iterators = next_iterators

import math

def allocate_shares(total: int, weights: list) -> list[int]:
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must be non-empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    W = sum(weights)
    if W == 0:
        raise ValueError("sum of weights must be positive")

    if total == 0:
        return [0] * len(weights)

    quotas = [total * w / W for w in weights]
    floors = [math.floor(q) for q in quotas]
    allocated = sum(floors)
    remaining = total - allocated

    if remaining > 0:
        remainders = [quotas[i] - floors[i] for i in range(len(weights))]
        # Sort by remainder descending, breaking ties by lower index
        sorted_indices = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
        for i in range(remaining):
            floors[sorted_indices[i]] += 1

    return floors

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity = capacity
        self._data = OrderedDict()  # key -> (value, stored_time, ttl)
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _is_dead(self, entry, now):
        _, stored_time, ttl = entry
        if ttl is None:
            return False
        return now >= stored_time + ttl

    def _purge(self, now):
        dead_keys = [k for k, e in self._data.items() if self._is_dead(e, now)]
        for k in dead_keys:
            del self._data[k]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive or None")
        self._purge(now)
        if key in self._data:
            self._data[key] = (value, now, ttl)
            self._data.move_to_end(key)
        else:
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
                self._evictions += 1
            self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._data:
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        return len(self._data)

from typing import List, Tuple

def max_sessions(intervals: List[Tuple[int, int]], gap: int) -> int:
    if not intervals:
        return 0
    intervals.sort(key=lambda x: x[1])
    count = 0
    last_end = float('-inf')
    for start, end in intervals:
        if start >= last_end + gap:
            count += 1
            last_end = end
    return count

def best_circular_selection(values, k):
    if k == 0:
        return 0

    n = len(values)

    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError

    if n == 2:
        if k == 1:
            return max(values)
        raise ValueError

    def linear_selection(arr, k):
        if k == 0:
            return 0
        m = len(arr)
        if m == 0:
            raise ValueError
        INF = float('-inf')
        prev2 = [INF] * (k + 1)
        prev2[0] = 0
        prev1 = [INF] * (k + 1)
        prev1[0] = 0
        for i in range(m):
            curr = [INF] * (k + 1)
            curr[0] = 0
            for j in range(1, k + 1):
                best = prev1[j]
                val = prev2[j - 1]
                if val != INF:
                    best = max(best, val + arr[i])
                curr[j] = best
            prev2 = prev1
            prev1 = curr
        result = prev1[k]
        if result == INF:
            raise ValueError
        return result

    INF = float('-inf')
    best = INF

    # Case 1: Element 0 not selected, choose k from indices 1..n-1 (linear)
    try:
        best = linear_selection(values[1:], k)
    except ValueError:
        pass

    # Case 2: Element 0 selected, choose k-1 from indices 2..n-2 (linear)
    try:
        val = values[0] + linear_selection(values[2:n-1], k - 1)
        best = max(best, val)
    except ValueError:
        pass

    if best == INF:
        raise ValueError
    return best

def kth_root_floor(n: int, k: int) -> int:
    if n < 0 or k < 1:
        raise ValueError
    if n <= 1:
        return n
    if k == 1:
        return n
    b = n.bit_length()
    if k >= b:
        return 1
    lo = 1
    hi = 1 << ((b + k - 1) // k)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if pow(mid, k) <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str, got %s" % type(text).__name__)
    if not text or text.isspace():
        raise ValueError("empty duration")
    i = 0
    n = len(text)
    seen = set()
    last_order = -1
    order = {'h': 0, 'm': 1, 's': 2}
    values = {}
    while i < n:
        if not text[i].isdigit():
            raise ValueError("malformed duration")
        j = i
        while j < n and text[j].isdigit():
            j += 1
        if j >= n or text[j] not in 'hms':
            raise ValueError("malformed duration")
        unit = text[j]
        if unit in seen:
            raise ValueError("malformed duration")
        if order[unit] <= last_order:
            raise ValueError("malformed duration")
        seen.add(unit)
        last_order = order[unit]
        values[unit] = int(text[i:j])
        i = j + 1
    if not seen:
        raise ValueError("malformed duration")
    return values.get('h', 0) * 3600 + values.get('m', 0) * 60 + values.get('s', 0)

def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError
    P = [0] * (n + 1)
    mod = 0
    for i, val in enumerate(deltas):
        mod = (mod + val) % k
        P[i + 1] = mod
    count = {}
    total = 0
    for j in range(n + 1):
        if j > hi:
            i_rem = j - hi - 1
            m = P[i_rem]
            c = count[m] - 1
            if c == 0:
                del count[m]
            else:
                count[m] = c
        if j >= lo:
            i_add = j - lo
            m = P[i_add]
            count[m] = count.get(m, 0) + 1
            total += count.get(P[j], 0)
    return total

import unicodedata

def truncate_display(s: str, width: int) -> str:
    if width < 0:
        raise ValueError("width must be non-negative")
    if width == 0 or not s:
        return ""

    unit_end_indices = []
    current_unit_start = None

    for i, ch in enumerate(s):
        cat = unicodedata.category(ch)
        if cat in ('Mn', 'Mc', 'Me'):
            if current_unit_start is None:
                current_unit_start = i
            # else: join the current unit
        else:
            if current_unit_start is not None:
                unit_end_indices.append(i)
            current_unit_start = i

    if current_unit_start is not None:
        unit_end_indices.append(len(s))

    if width >= len(unit_end_indices):
        return s
    return s[:unit_end_indices[width - 1]]

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")
    result = []
    # stack entries: (container_list, container_depth, next_index)
    # elements of a container at container_depth are at depth container_depth + 1
    stack = [(nested, 0, 0)]
    while stack:
        container, cdepth, idx = stack[-1]
        if idx >= len(container):
            stack.pop()
            continue
        stack[-1] = (container, cdepth, idx + 1)
        item = container[idx]
        item_depth = cdepth + 1
        if isinstance(item, list) and item_depth <= max_depth:
            stack.append((item, item_depth, 0))
        else:
            result.append(item)
    return result

class CountingBag:
    def __init__(self):
        self._counts = {}
        self._entry = {}
        self._clock = 0

    def add(self, item) -> int:
        if item not in self._counts:
            self._entry[item] = self._clock
            self._clock += 1
            self._counts[item] = 1
        else:
            self._counts[item] += 1
        return self._counts[item]

    def discard(self, item) -> bool:
        if item not in self._counts:
            return False
        self._counts[item] -= 1
        if self._counts[item] == 0:
            del self._counts[item]
            del self._entry[item]
        return True

    def count(self, item) -> int:
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        return sum(self._counts.values())

    def distinct(self) -> int:
        return len(self._counts)

    def most_common(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        ordered = sorted(
            self._counts.items(),
            key=lambda kv: (-kv[1], self._entry[kv[0]])
        )
        return ordered[:k]

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if isinstance(low, bool) or isinstance(high, bool) or not isinstance(low, (int, float)) or not isinstance(high, (int, float)):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")

    for i in range(len(values)):
        v = values[i]
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise TypeError(f"index {i}")

    result = []
    for i in range(len(values)):
        v = values[i]
        if v < low:
            result.append(low)
        elif v > high:
            result.append(high)
        else:
            result.append(v)
    return result

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    result = {}
    for i, row in enumerate(rows):
        # a. tuple or wrong length
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"row {i} is not a tuple of exactly 3 elements")
        category, amount, refunded = row
        # b. category
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i} has an invalid category")
        # c. amount type (bool not allowed)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i} has an invalid amount type")
        # d. amount < 0
        if amount < 0:
            raise ValueError(f"row {i} has a negative amount")
        # e. refunded
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i} has an invalid refunded flag")

        if category not in result:
            result[category] = {"count": 0, "gross": 0.0, "net": 0.0, "largest": float("-inf")}
        entry = result[category]
        entry["count"] += 1
        entry["gross"] += float(amount)
        if not refunded:
            entry["net"] += float(amount)
        if float(amount) > entry["largest"]:
            entry["largest"] = float(amount)

    # finalize: largest should be float; for empty categories impossible, but ensure float
    for entry in result.values():
        entry["gross"] = float(entry["gross"])
        entry["net"] = float(entry["net"])
        entry["largest"] = float(entry["largest"])
    return result

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
        graph[pkg] = sorted(set(ds))
    order = []
    visiting = set()
    visited = set()

    def visit(node):
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        if node in visited:
            return
        visiting.add(node)
        for dep in graph[node]:
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        visit(node)
    return order

import heapq

def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    if cap < 1:
        raise ValueError("cap must be at least 1")
    if not jobs:
        return 0

    # Sort by deadline (and then by bounty, though order among equal deadlines doesn't matter)
    jobs.sort()
    heap = []
    for d, p in jobs:
        heapq.heappush(heap, p)
        if len(heap) > cap * d:
            heapq.heappop(heap)

    return sum(heap)
